val monitor = CoroutineScope(SupervisorJob() + Dispatchers.Default)
monitor.launch {
    arrivals                                   // Flow<Message> of the watched flow
        .timeout(silenceBudget)                // no item within budget -> TimeoutCancellationException
        .catch { e ->
            if (e is TimeoutCancellationException) raise(subject, silenceBudget) else throw e
        }
        .collect { markAlive(it) }             // every arrival just proves liveness
}
